CREATE DEFINER=`root`@`localhost` PROCEDURE `componenteRelationSub`(
 idComponente    nvarchar(50)
)
BEGIN
		select distinct c.Codigo,c.descripcion,if(sc.especial=1,'SI','NO') as 'Vidrio/Panel' from arquitectdb.subcomponentes sc
			inner join arquitectdb.componentes_detalle cpd on sc.Id_Subcomponente = cpd.Id_Subcomponente
			inner join arquitectdb.componentes c on c.Id_Componente = cpd.Id_Componente
			where sc.Codigo_Homologacion = idComponente
            union all
            select c.Codigo,c.descripcion,if(sc.especial=1,'SI','NO') as 'Vidrio/Panel' from arquitectdb.subcomponentes sc
			inner join arquitectdb.componentes_especial_detalle cpd on sc.Id_Subcomponente = cpd.Id_Subcomponente
			inner join arquitectdb.componentes c on c.Id_Componente = cpd.Id_Componente_especial
			where sc.Codigo_Homologacion = idComponente;
END ;;
