CREATE DEFINER=`root`@`localhost` PROCEDURE `componentesConsultar`(
  pCadena nvarchar(100)
)
BEGIN
    SELECT Id_Componente,Codigo,Descripcion 
    FROM arquitectdb.componentes
    WHERE CONCAT(Codigo , "-" , Descripcion) lIKE concat('%',  pCadena , '%');
END ;;
