   pCodigo nvarchar(50),
   pDescripcion nvarchar(300),
   pIdComponente int
)
BEGIN
    UPDATE arquitectdb.componentes_Especial SET codigo = pCodigo, 
												descripcion = pDescripcion
	WHERE Id_Componente_Especial = pIdComponente;
END ;;
