CREATE DEFINER=`root`@`localhost` PROCEDURE `spComponenteGetCodigoAcabado`(
 pCodigo       nvarchar(50) 
)
BEGIN

    SELECT concat(codigo,'-',ifnull(acabados.codigo_homologacion,"00")) Codigo 
    FROM arquitectdb.componentes 
    join arquitectdb.acabados on componentes.AcabadoPrincipal = acabados.Id_Acabado
    where codigo = pCodigo;    
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
