CREATE DEFINER=`root`@`localhost` PROCEDURE `spComponenteVidrioPanelInsert`(
	pCodigo  nvarchar(50),
	pAltura  int,
	pAchura  Int 
)
BEGIN

  INSERT proyecto_vidriopanel (Codigo,
                               Altura,
                               Anchura) 
                                     VALUES(pCodigo, 
                                             pAltura,
                                             pAchura);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
