DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `spSubComponenteAgrupar`(
pDesperdicio float
)
BEGIN
  SET SQL_SAFE_UPDATES = 0;
  
  SELECT proy.Id_Subcomponente,
		concat(subcomponente.codigo_homologacion, "-",acabado.codigo_homologacion ) codigo,
        subcomponente.Descripcion,
        acabado.Descripcion AcabadoDesc,
        CASE WHEN proy.Id_Unidad_Medida != 1 
        THEN (SELECT SUM(proyect.cantidad) FROM arquitectdb.proyecto proyect WHERE proyect.Id_Subcomponente = proy.Id_Subcomponente and proyect.Id_Unidad_Medida = proy.Id_Unidad_Medida and  proyect.medidaAdicional = proy.medidaAdicional)
		WHEN mod((SELECT SUM(proyect.medida) FROM arquitectdb.proyecto proyect WHERE proyect.Id_Subcomponente = proy.Id_Subcomponente 
        and proyect.Id_Unidad_Medida = proy.Id_Unidad_Medida) / proy.medidaAdicional,1) < 0.1 then
         FLOOR((SELECT SUM(proyect.medida) FROM arquitectdb.proyecto proyect WHERE proyect.Id_Subcomponente = proy.Id_Subcomponente 
        and proyect.Id_Unidad_Medida = proy.Id_Unidad_Medida) / proy.medidaAdicional ) * pDesperdicio
        else 
        ceiling(((SELECT SUM(proyect.medida) FROM arquitectdb.proyecto proyect WHERE proyect.Id_Subcomponente = proy.Id_Subcomponente 
        and proyect.Id_Unidad_Medida = proy.Id_Unidad_Medida) * pDesperdicio) / proy.medidaAdicional) END cantidad,        
		proy.medidaAdicional medidaC,
        CASE WHEN proy.Id_Unidad_Medida != 1 THEN 0
        ELSE (SELECT SUM(proyect.medida) FROM arquitectdb.proyecto proyect WHERE proyect.Id_Subcomponente = proy.Id_Subcomponente and proyect.Id_Unidad_Medida = proy.Id_Unidad_Medida) * pDesperdicio END medidaCalculada,
        fnUnidadCalculada(proy.Id_Unidad_Medida) unidaMedida
  FROM arquitectdb.proyecto proy 
  JOIN subcomponentes subcomponente ON proy.Id_Subcomponente = subcomponente.Id_Subcomponente
  JOIN acabados acabado ON acabado.Id_Acabado = subcomponente.Id_Acabado
  GROUP BY proy.Id_Subcomponente, proy.Id_Unidad_Medida, proy.medidaAdicional ;
  
   DELETE FROM proyecto;
  
END ;;
DELIMITER ;
